// Internal migration control: public continuation admission remains closed.
// Every checkpoint here is generated by the production SDK and delivery path.
func TestNativeGraphContinuationSDKFlow(t *testing.T) {
	for _, domain := range []string{"", "WFCONTINUATIONSDK"} {
		name := "R1"
		if domain != "" {
			name = "R3Domain"
		}
		t.Run(name, func(t *testing.T) { testNativeGraphContinuationSDKFlow(t, domain, false, false, false, false) })
	}
}
